commit 1e9dba82debbbadef602e017abeac3780f739cdd
Author: missingbulb <73882448+missingbulb@users.noreply.github.com>
Date:   Mon Aug 24 12:50:50 2026 +0300

    Ask the account where a Worker would even be published (#89)

    The deploy reached production, applied the migrations, and then failed: the
    account had never registered a workers.dev subdomain, so `wrangler deploy` had
    nowhere to publish to. It asks for one interactively, and on a runner that is a
    failed deploy — after the schema has already moved.

    The preflight said production was ready, because it only ever asked wrangler,
    and wrangler has no command for this. It now reads the account directly for the
    subdomain — a GET, the only one here, and the whole reason the wrangler runner
    stays closed to everything else.

    The failure that led here also arrived with its actionable half missing: the
    URL wrangler sends you to sits after a blank line, and the reason stopped at the
    first one. It now crosses a single blank and stops at two.

    Refs #27

diff --git a/dev/gates/provisioning.test.ts b/dev/gates/provisioning.test.ts
index c7c0bf8..3e48233 100644
--- a/dev/gates/provisioning.test.ts
+++ b/dev/gates/provisioning.test.ts
@@ -190,6 +190,31 @@ test('the reason under the error line comes with it', () => {
   );
 });

+test('a blank line does not cut the reason off before the link it is pointing at', () => {
+  // What `wrangler deploy` says on an account with no workers.dev subdomain, verbatim from
+  // run 32640257251. The URL — the whole actionable half — comes after a blank line.
+  const output = [
+    ' ⛅️ wrangler 4.125.0',
+    '? Would you like to register a workers.dev subdomain now?',
+    '🤖 Using fallback value in non-interactive context: no',
+    '▲ [WARNING] You need to register a workers.dev subdomain before publishing to workers.dev',
+    '',
+    '✘ [ERROR] You can either deploy your worker to one or more routes by specifying them in your wrangler.toml file, or register a workers.dev subdomain here:',
+    '',
+    '  https://dash.cloudflare.com/abc/workers/onboarding',
+    '',
+    '',
+    '🪵  Logs were written to "/home/runner/.config/.wrangler/logs/wrangler.log"',
+  ].join('\n');
+  assert.match(firstUsefulLine(output), /register a workers\.dev subdomain here/);
+  assert.match(firstUsefulLine(output), /dash\.cloudflare\.com\/abc\/workers\/onboarding/);
+});
+
+test('two blank lines end it, so the whole log never becomes the reason', () => {
+  const output = ['✘ [ERROR] Something failed.', '', '', 'unrelated trailing chatter'].join('\n');
+  assert.equal(firstUsefulLine(output), 'Something failed.');
+});
+
 test("wrangler's own error line is what gets reported, not its banner", () => {
   const output = [
     ' ⛅️ wrangler 4.125.0',
diff --git a/dev/tools/cloudflare.ts b/dev/tools/cloudflare.ts
index ab0d75f..141243d 100644
--- a/dev/tools/cloudflare.ts
+++ b/dev/tools/cloudflare.ts
@@ -30,10 +30,14 @@ export type Resource = {
   create: string[];
 };

+/** Where a human would look at one part of the account, given an id if we have one. */
+export const dashboardUrl = (section: string, accountId?: string): string =>
+  accountId ? `https://dash.cloudflare.com/${accountId}/${section}` : 'https://dash.cloudflare.com/';
+
 const dashboard =
   (section: string) =>
   (accountId?: string): string =>
-    accountId ? `https://dash.cloudflare.com/${accountId}/${section}` : 'https://dash.cloudflare.com/';
+    dashboardUrl(section, accountId);

 export const D1_DATABASE = 'hitbut-corpus';
 /** What `wrangler.toml` carries until an account has handed out a real one. */
@@ -106,8 +110,13 @@ export const RESOURCES: Resource[] = [
  * The marked line is a **headline**, and the part that says what to do about it comes on the
  * lines under it: `wrangler r2 bucket list` reports "A request to the Cloudflare API
  * (/accounts/…/r2/buckets) failed." and puts the code that separates a missing token scope
- * from an un-onboarded product underneath. Take the continuation with it, to the first blank
- * line or next marker, or the report names a failure nobody can act on.
+ * from an un-onboarded product underneath. Take the continuation with it, or the report names
+ * a failure nobody can act on.
+ *
+ * A blank line does not end the continuation. Wrangler's own layout puts the URL you are
+ * being sent to — the whole actionable half of "register a workers.dev subdomain here:" — on
+ * its own line after one. Stop at the next marker, at wrangler's boilerplate, or at a second
+ * consecutive blank; a handful of lines is the cap either way.
  */
 // eslint-disable-next-line no-control-regex -- ANSI escapes are exactly what is being stripped
 export const stripAnsi = (output: string): string => output.replace(/\u001b\[[0-9;]*m/g, '');
@@ -123,13 +132,21 @@ export function firstUsefulLine(output: string): string {
   const noise = /^wrangler \d|Logs were written|create an issue at|telemetry/;
   const at = lines.findIndex((line) => line.includes('\u2718'));

+  const CONTINUATION_LINES = 4;
   let reason = '';
   if (at !== -1) {
     const block = [lines[at] as string];
+    let blanks = 0;
     for (const line of lines.slice(at + 1)) {
       const next = tidy(line);
-      if (!next || /[\u2718\u25b2]/.test(line) || noise.test(next)) break;
+      if (!next) {
+        if (++blanks > 1) break;
+        continue;
+      }
+      if (/[\u2718\u25b2]/.test(line) || noise.test(next)) break;
+      blanks = 0;
       block.push(line);
+      if (block.length > CONTINUATION_LINES) break;
     }
     reason = block.map(tidy).filter(Boolean).join(' ');
   }
@@ -137,6 +154,31 @@ export function firstUsefulLine(output: string): string {
   return reason.length > 400 ? `${reason.slice(0, 400)}…` : reason;
 }

+/**
+ * A read of the Cloudflare API that wrangler has no command for. The workers.dev subdomain is
+ * one such fact — there is no `wrangler subdomain`, and a deploy that has nowhere to publish
+ * to is exactly what the preflight exists to catch before it happens. GET only: this file's
+ * whole point is that nothing here can destroy anything.
+ */
+export async function accountRead<T>(path: string): Promise<{ ok: true; body: T } | { ok: false; reason: string }> {
+  const account = process.env.CLOUDFLARE_ACCOUNT_ID;
+  const token = process.env.CLOUDFLARE_API_TOKEN;
+  if (!account || !token) return { ok: false, reason: 'no account id or token in the environment' };
+  try {
+    const response = await fetch(`https://api.cloudflare.com/client/v4/accounts/${account}/${path}`, {
+      headers: { Authorization: `Bearer ${token}` },
+    });
+    const body = (await response.json()) as { success?: boolean; result?: T; errors?: { message?: string }[] };
+    if (!response.ok || body.success === false) {
+      const said = body.errors?.map((error) => error.message).filter(Boolean).join('; ');
+      return { ok: false, reason: said || `HTTP ${response.status}` };
+    }
+    return { ok: true, body: body.result as T };
+  } catch (error) {
+    return { ok: false, reason: (error as Error).message };
+  }
+}
+
 /**
  * The JSON array in wrangler's output. `--json` still leaves warnings and the version banner
  * around it, and those carry brackets of their own (`[WARNING]`), so this takes the first `[`
diff --git a/dev/tools/preflight.ts b/dev/tools/preflight.ts
index 019e7f1..0559a31 100644
--- a/dev/tools/preflight.ts
+++ b/dev/tools/preflight.ts
@@ -12,6 +12,8 @@ import {
   D1_DATABASE,
   PLACEHOLDER_DATABASE_ID,
   RESOURCES,
+  accountRead,
+  dashboardUrl,
   databaseIdIn,
   look,
   missing,
@@ -30,7 +32,7 @@ type Check = {
   why: string;
   /** Where to go to fix it: a dashboard page, a settings page, or the command that does it. */
   fix: string;
-  run: () => Result;
+  run: () => Result | Promise<Result>;
 };

 function fromEnvironment(name: string): Result {
@@ -46,6 +48,20 @@ function databaseIdPinned(): Result {
     : present(`pinned to ${id}`);
 }

+/**
+ * Where a deployed Worker can be reached. Without one `wrangler deploy` has nowhere to
+ * publish to and asks interactively, which on a runner is a failure after the migrations
+ * have already been applied. There is no `wrangler` command for it, so this reads the
+ * account directly.
+ */
+async function workersDevSubdomain(): Promise<Result> {
+  const read = await accountRead<{ subdomain?: string | null }>('workers/subdomain');
+  if (!read.ok) return unknown(`could not ask the account — ${read.reason}`);
+  return read.body?.subdomain
+    ? present(`${read.body.subdomain}.workers.dev`)
+    : missing('the account has never registered one');
+}
+
 const CHECKS: Check[] = [
   {
     label: 'secret CLOUDFLARE_ACCOUNT_ID',
@@ -61,6 +77,13 @@ const CHECKS: Check[] = [
     fix: `paste it at ${SECRETS_SETTINGS}`,
     run: () => fromEnvironment('CLOUDFLARE_API_TOKEN'),
   },
+  {
+    label: 'workers.dev subdomain',
+    required: true,
+    why: 'the Worker has nowhere to be published to, and wrangler asks for one interactively — which on a runner is a failed deploy, after the migrations have already been applied',
+    fix: `register one at ${dashboardUrl('workers/onboarding', process.env.CLOUDFLARE_ACCOUNT_ID)} — one-time, and it names the Worker's host`,
+    run: workersDevSubdomain,
+  },
   {
     label: 'wrangler.toml database_id',
     required: true,
@@ -79,7 +102,7 @@ const CHECKS: Check[] = [

 const MARK: Record<Result['state'], string> = { present: 'ok  ', missing: 'MISS', unknown: '??  ' };

-const results = CHECKS.map((check) => ({ check, result: check.run() }));
+const results = await Promise.all(CHECKS.map(async (check) => ({ check, result: await check.run() })));

 console.log('\nhitbut preflight — reads production, changes nothing\n');
 for (const { check, result } of results) {

